-- | Recursive-descent parser for the kUML native DSL.
--
-- Grammar (EBNF-ish):
--
--   diagram    = "diagram" STRING "{" item* "}"
--   item       = classifier | relationship
--   classifier = ["abstract"] ("class"|"interface") IDENT [ "{" member* "}" ]
--              | "enum" IDENT [ "{" literal* "}" ]
--   member     = VIS IDENT ( ":" IDENT | "(" params ")" [ ":" IDENT ] )?
--   params     = [ param ("," param)* ]
--   param      = IDENT [ ":" IDENT ]
--   literal    = IDENT [ ";" | "," ]
--   relationship = ("association"|"composition"|"aggregation"
--                  |"generalization"|"realization"|"dependency") IDENT IDENT
--
-- Threaded with fully explicit nested @case@ over @Either String@ — no
-- monad, no higher-order continuation combinator. JHC 0.8.2 both lacks a
-- @Monad (Either e)@ instance AND (empirically) fails to emit some of the
-- closures generated by a continuation-passing @bindP@ here, producing
-- undefined @fx…@ references at link time. First-order case-threading sidesteps
-- both. Verbose, but it builds identically on GHC and JHC.
module Kuml.Parser (parseDiagram) where

import Kuml.Lexer (Token(..), tokenize, tokLabel)
import Kuml.Types

-- | Parse source text into a 'Diagram' or a diagnostic message.
parseDiagram :: String -> Either String Diagram
parseDiagram src =
  case pDiagram (tokenize src) of
    Left e -> Left e
    Right (d, rest) ->
      case rest of
        [] -> Right d
        _  -> Left ("unexpected trailing tokens after diagram: " ++ showToks 6 rest)

-- ── helpers ──────────────────────────────────────────────────────────────

showToks :: Int -> [Token] -> String
showToks n ts = unwords (map tokLabel (take n ts))

expectKw :: String -> [Token] -> Either String [Token]
expectKw kw (TIdent s : ts)
  | s == kw = Right ts
expectKw kw ts = Left ("expected '" ++ kw ++ "', got: " ++ showToks 3 ts)

expectTok :: Token -> [Token] -> Either String [Token]
expectTok want (t:ts)
  | t == want = Right ts
expectTok want ts = Left ("expected " ++ tokLabel want ++ ", got: " ++ showToks 3 ts)

takeIdent :: [Token] -> Either String (String, [Token])
takeIdent (TIdent s : ts) = Right (s, ts)
takeIdent ts = Left ("expected identifier, got: " ++ showToks 3 ts)

takeStr :: [Token] -> Either String (String, [Token])
takeStr (TStr s : ts) = Right (s, ts)
takeStr ts = Left ("expected quoted string, got: " ++ showToks 3 ts)

relKeyword :: String -> Maybe RelKind
relKeyword "association"    = Just RAssociation
relKeyword "composition"    = Just RComposition
relKeyword "aggregation"    = Just RAggregation
relKeyword "generalization" = Just RGeneralization
relKeyword "realization"    = Just RRealization
relKeyword "dependency"     = Just RDependency
relKeyword _                = Nothing

-- ── diagram ────────────────────────────────────────────────────────────────

pDiagram :: [Token] -> Either String (Diagram, [Token])
pDiagram ts0 =
  case expectKw "diagram" ts0 of
    Left e -> Left e
    Right ts1 ->
      case takeStr ts1 of
        Left e -> Left e
        Right (nm, ts2) ->
          case expectTok TLBrace ts2 of
            Left e -> Left e
            Right ts3 ->
              case pItems ts3 of
                Left e -> Left e
                Right (items, ts4) ->
                  case expectTok TRBrace ts4 of
                    Left e -> Left e
                    Right ts5 ->
                      case collectItems items of
                        (cls, rels) -> Right (Diagram nm cls rels, ts5)

data Item = ItClass Classifier | ItRel Relationship

-- Partition items in one first-order pass.
collectItems :: [Item] -> ([Classifier], [Relationship])
collectItems = go [] []
  where
    go cs rs [] = (reverse cs, reverse rs)
    go cs rs (ItClass c : xs) = go (c : cs) rs xs
    go cs rs (ItRel r : xs)   = go cs (r : rs) xs

pItems :: [Token] -> Either String ([Item], [Token])
pItems ts =
  case ts of
    (TRBrace : _) -> Right ([], ts)
    []            -> Right ([], ts)
    _ ->
      case pItem ts of
        Left e -> Left e
        Right (it, ts1) ->
          case pItems ts1 of
            Left e -> Left e
            Right (its, ts2) -> Right (it : its, ts2)

pItem :: [Token] -> Either String (Item, [Token])
pItem ts =
  case ts of
    (TIdent "abstract" : rest) ->
      case expectKw "class" rest of
        Left e -> Left e
        Right rest1 -> classItem (KClass True) rest1
    (TIdent "class" : rest)     -> classItem (KClass False) rest
    (TIdent "interface" : rest) -> classItem KInterface rest
    (TIdent "enum" : rest) ->
      case pEnumBody rest of
        Left e -> Left e
        Right (c, ts1) -> Right (ItClass c, ts1)
    (TIdent kw : rest) ->
      case relKeyword kw of
        Just k  -> pRel k rest
        Nothing -> Left ("unknown statement keyword '" ++ kw ++ "'")
    _ -> Left ("expected a class/interface/enum/relationship, got: " ++ showToks 3 ts)

classItem :: ClassifierKind -> [Token] -> Either String (Item, [Token])
classItem kind ts =
  case pClassBody kind ts of
    Left e -> Left e
    Right (c, ts1) -> Right (ItClass c, ts1)

pRel :: RelKind -> [Token] -> Either String (Item, [Token])
pRel k ts =
  case takeIdent ts of
    Left e -> Left e
    Right (a, ts1) ->
      case takeIdent ts1 of
        Left e -> Left e
        Right (b, ts2) -> Right (ItRel (Relationship k a b), ts2)

-- ── class / interface bodies ────────────────────────────────────────────────

pClassBody :: ClassifierKind -> [Token] -> Either String (Classifier, [Token])
pClassBody kind ts0 =
  case takeIdent ts0 of
    Left e -> Left e
    Right (nm, ts1) ->
      case ts1 of
        (TLBrace : rest) ->
          case pMembers rest of
            Left e -> Left e
            Right (ms, ts2) ->
              case expectTok TRBrace ts2 of
                Left e -> Left e
                Right ts3 ->
                  case splitMembers ms of
                    (as, os) -> Right (Classifier kind nm as os [], ts3)
        _ -> Right (Classifier kind nm [] [] [], ts1)

data Member = MAttr Attribute | MOp Operation

splitMembers :: [Member] -> ([Attribute], [Operation])
splitMembers = go [] []
  where
    go as os [] = (reverse as, reverse os)
    go as os (MAttr a : xs) = go (a : as) os xs
    go as os (MOp o : xs)   = go as (o : os) xs

pMembers :: [Token] -> Either String ([Member], [Token])
pMembers ts =
  case ts of
    (TRBrace : _) -> Right ([], ts)
    []            -> Right ([], ts)
    _ ->
      case pMember ts of
        Left e -> Left e
        Right (m, ts1) ->
          case pMembers ts1 of
            Left e -> Left e
            Right (ms, ts2) -> Right (m : ms, ts2)

pMember :: [Token] -> Either String (Member, [Token])
pMember (TVis v : ts0) =
  case takeIdent ts0 of
    Left e -> Left e
    Right (nm, ts1) ->
      case ts1 of
        (TLParen : rest) -> pOpMember (visFromChar v) nm rest
        (TColon : rest) ->
          case takeIdent rest of
            Left e -> Left e
            Right (ty, ts2) -> Right (MAttr (Attribute (visFromChar v) nm ty), ts2)
        _ -> Right (MAttr (Attribute (visFromChar v) nm ""), ts1)
pMember ts = Left ("expected a member (+/-/#/~ ...), got: " ++ showToks 3 ts)

pOpMember :: Visibility -> String -> [Token] -> Either String (Member, [Token])
pOpMember vis nm rest =
  case pParams rest of
    Left e -> Left e
    Right (ps, ts2) ->
      case expectTok TRParen ts2 of
        Left e -> Left e
        Right ts3 ->
          case pOptReturn ts3 of
            Left e -> Left e
            Right (ret, ts4) -> Right (MOp (Operation vis nm ps ret), ts4)

visFromChar :: Char -> Visibility
visFromChar '+' = VPublic
visFromChar '-' = VPrivate
visFromChar '#' = VProtected
visFromChar '~' = VPackage
visFromChar _   = VPublic

pOptReturn :: [Token] -> Either String (Maybe String, [Token])
pOptReturn (TColon : ts) =
  case takeIdent ts of
    Left e -> Left e
    Right (ty, ts1) -> Right (Just ty, ts1)
pOptReturn ts = Right (Nothing, ts)

pParams :: [Token] -> Either String ([Param], [Token])
pParams ts =
  case ts of
    (TRParen : _) -> Right ([], ts)
    _ ->
      case pParam ts of
        Left e -> Left e
        Right (p, ts1) ->
          case ts1 of
            (TComma : rest) ->
              case pParams rest of
                Left e -> Left e
                Right (ps, ts2) -> Right (p : ps, ts2)
            _ -> Right ([p], ts1)

pParam :: [Token] -> Either String (Param, [Token])
pParam ts0 =
  case takeIdent ts0 of
    Left e -> Left e
    Right (nm, ts1) ->
      case ts1 of
        (TColon : rest) ->
          case takeIdent rest of
            Left e -> Left e
            Right (ty, ts2) -> Right (Param nm ty, ts2)
        _ -> Right (Param nm "", ts1)

-- ── enum body ────────────────────────────────────────────────────────────

pEnumBody :: [Token] -> Either String (Classifier, [Token])
pEnumBody ts0 =
  case takeIdent ts0 of
    Left e -> Left e
    Right (nm, ts1) ->
      case ts1 of
        (TLBrace : rest) ->
          case pLiterals rest of
            Left e -> Left e
            Right (lits, ts2) ->
              case expectTok TRBrace ts2 of
                Left e -> Left e
                Right ts3 -> Right (Classifier KEnum nm [] [] lits, ts3)
        _ -> Right (Classifier KEnum nm [] [] [], ts1)

pLiterals :: [Token] -> Either String ([String], [Token])
pLiterals ts =
  case ts of
    (TRBrace : _)   -> Right ([], ts)
    []              -> Right ([], ts)
    (TSemi : rest)  -> pLiterals rest
    (TComma : rest) -> pLiterals rest
    (TIdent s : rest) ->
      case pLiterals rest of
        Left e -> Left e
        Right (ls, ts1) -> Right (s : ls, ts1)
    _ -> Left ("expected an enum literal, got: " ++ showToks 3 ts)
